$logFile = __DIR__ . '/storage/trace.log';

function appendTrace(string $entry, string $file): void
{
    file_put_contents($file, $entry . PHP_EOL, FILE_APPEND);
}

// 外部输入入口：追踪 ID 来自客户端请求头，action 来自查询参数
$traceId = $_SERVER['HTTP_X_TRACE_ID'] ?? '';
$action  = $_GET['action'] ?? 'ping';

if ($traceId === '') {
    http_response_code(400);
    exit('missing trace id');
}

// 构造追踪条目：traceId 仅作为数据位拼入，未过滤换行与控制字符
$entry = sprintf('[%s] trace=%s action=%s', date('Y-m-d H:i:s'), $traceId, $action);
appendTrace($entry, $logFile);

echo 'trace recorded';
