class CallbackLogger {
    private $file;
    public function __construct($file) { $this->file = $file; }
    public function info($msg) {
        file_put_contents($this->file, date('[Y-m-d H:i:s] ') . $msg . PHP_EOL, FILE_APPEND);
    }
    public function error($msg) { $this->info('ERROR ' . $msg); }
}

define('MERCHANT_KEY', getenv('PAY_MERCHANT_KEY') ?: 'unset');
$logger = new CallbackLogger('/var/log/pay/callback.log');

// 外部输入入口：支付网关 POST 异步回调参数
$orderId  = $_POST['order_id']  ?? '';
$cardNo   = $_POST['card_no']   ?? '';   // 银行卡号
$payToken = $_POST['pay_token'] ?? '';   // 支付凭据 token
$amount   = $_POST['amount']    ?? '0';
$sign     = $_POST['sign']      ?? '';

$expected = md5($orderId . '|' . $amount . '|' . MERCHANT_KEY);
if (!hash_equals($expected, $sign)) {
    // 验签失败：整笔回调参数原样落日志便于排查
    $logger->error("sign verify failed: order={$orderId}, card_no={$cardNo}, pay_token={$payToken}, amount={$amount}");
    http_response_code(403);
    exit('invalid sign');
}

// 回调成功后仍将卡号与 token 写入审计日志
$logger->info("callback ok: order={$orderId}, card_no={$cardNo}, pay_token={$payToken}, amount={$amount}");
