	"os"
)

// 安全告警日志服务：接收监控探针上报的告警消息并写入安全告警日志
var alertLogger = log.New(os.Stdout, "[SEC-ALERT] ", log.LstdFlags)

func alertHandler(w http.ResponseWriter, r *http.Request) {
	// 外部输入入口：告警消息由客户端通过查询参数 msg 提交
	alertMsg := r.URL.Query().Get("msg")
	if alertMsg == "" {
		http.Error(w, "missing msg", http.StatusBadRequest)
		return
	}
	// 服务器内部事件序号，作为格式化实参传入
	seq := r.URL.Query().Get("seq")
	// 漏洞点：alertMsg 未经处理直接占据 Printf 的格式串参数位
	alertLogger.Printf(alertMsg, seq)
	w.Write([]byte("alert accepted"))
}

func main() {
	http.HandleFunc("/alert", alertHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
```

## 漏洞分析

1. **定位外部输入入口（源）**：line 14 `alertMsg := r.URL.Query().Get("msg")`，HTTP 查询参数 `msg` 完全由客户端控制，是清晰的外部输入入口；line 20 的 `seq` 同样来自请求，将作为格式化实参参与输出。
2. **定位日志写入点（汇）并判定参数位型**：line 22 `alertLogger.Printf(alertMsg, seq)` 中，`alertMsg` 被直接传入 Printf 系列函数的第一个参数——即**格式串位**（format string 参数位），输入本身就是日志模板，而非经 `Printf("%s", alertMsg)` 落在数据位。
3. **近邻辨析（117 vs 134）**：不是 117：输入是格式模板而非数据——输入占据格式串参数位而非数据参数位，属 134。攻击者提交 `msg=%s%x%v` 等格式动词可改写 `[SEC-ALERT]` 告警日志的结构与内容、触发 `%!s(MISSING)` 类格式化错误输出，并按所选动词反射内部实参 `seq`，甚至以超宽动词（如 `%99999999d`）造成资源耗尽；只有当输入作为数据位（如 `Printf("%s", alertMsg)`）且可注入换行伪造日志条目时才判 CWE-117，本例位型不符，排除 117。
4. **排除 532 / 312**：输入内容是攻击者任意文本，并非密码/token/密钥/卡号等敏感字面值，不构成 CWE-532；汇点是告警日志写入（`log.Logger` 日志流），不是文件/DB/缓存等非日志存储明文，不构成 CWE-312。
5. **防御与可达性核验**：line 15-18 仅做空值检查，对格式动词无任何过滤；line 14 至 line 22 数据流直接可达，全程无转义、无白名单、无常量化模板，漏洞真实成立。

